@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h3>Notepad</h3>

<textarea @bind="content" @bind:event="oninput" rows="15" style="width:100%;" placeholder="Type your notes here..."></textarea>

<div style="margin-top: 0.5rem; display: flex; align-items: center; gap: 1rem;">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span>Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private Timer? autoSaveTimer;
    private IJSObjectReference? module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Notepad.razor.js");

            var restored = await module.InvokeAsync<string?>("load");
            if (!string.IsNullOrEmpty(restored))
            {
                content = restored;
                savedContent = restored;
                StateHasChanged();
            }

            await module.InvokeVoidAsync("registerBeforeUnload");

            autoSaveTimer = new Timer(async _ => await AutoSave(), null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async Task AutoSave()
    {
        if (content != savedContent)
        {
            await InvokeAsync(async () =>
            {
                await Save();
                StateHasChanged();
            });
        }
    }

    private async Task SaveNow()
    {
        await Save();
    }

    private async Task Save()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("save", content);
            savedContent = content;
            lastSavedAt = DateTime.Now;
            await module.InvokeVoidAsync("setDirty", false);
        }
    }

    private async Task Clear()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
            await module.InvokeVoidAsync("setDirty", false);
        }
    }

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender, bool _)
    {
        // handled in the other overload
    }

    public async ValueTask DisposeAsync()
    {
        autoSaveTimer?.Dispose();
        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", false);
            await module.DisposeAsync();
        }
    }
}

